  {
    "id": "must_use_cart_for_trip",
    "text": "A shopper should obtain a cart during the shopping trip before leaving.",
    "abstraction": {
      "state_properties": {
        "carryingCart": "hasCart"
      },
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "carryingCart"
    },
    "justification": "The rule refers only to the domain role of having a cart, not to where carts are located in this particular store."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper should not leave the store without their cart.",
    "abstraction": {
      "state_properties": {
        "withoutCart": {
          "not": "hasCart"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "withoutCart"
        ]
      }
    },
    "justification": "The rule is tied to the general act of exiting while cartless, independent of the exit cell's coordinates."
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper should not take a cart into a single-file aisle bounded by shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "Single-file shelf aisles are defined by local geometry and shelf adjacency rather than by fixed coordinates."
  },
  {
    "id": "do_not_push_cart_into_single_file_aisle",
